import React, { useEffect, useCallback,useRef } from 'react';
import PropTypes from 'prop-types';
import Accordion from '../tools/finder__accordion';
import LabelCount from "./finder__filterLabel__count";
import type { FacetDetails } from '../../types/facet';
import type { QueryDetails } from '../../types/query';
import type { Update } from '../../types/update';
import type { Response } from '../../types/FBresponse';

type DrillDownProps = Update & {
    facet: FacetDetails;
    query: QueryDetails;
    response: Response;
    mobile?: boolean;
    matrixState?: boolean;
};

function Finder__DrillDown(props: DrillDownProps) {
    const facets = props.facet.drillDownFacets ?? [];
    const attemptedAutoSelects = useRef(new Set<string>());
    const hasValue = (value: string | string[] | undefined) =>
        Array.isArray(value) ? value.length > 0 : Boolean(value);

    const selectedCount = facets.filter((facet) =>
        hasValue(props.query.facets[facet.meta])
    ).length;

    const setFacet = useCallback((index: number, value: string) => {
        const newQuery = {
            ...props.query,
            facets: { ...props.query.facets },
        };

        facets.slice(index + 1).forEach((facet) => {
            delete newQuery.facets[facet.meta];
        });

        if (value) newQuery.facets[facets[index].meta] = value;
        else delete newQuery.facets[facets[index].meta];

        newQuery.startRank = 1;
        newQuery.misspelling = null;
        newQuery.interacted = true;

        props.update.query(newQuery);
        props.update.results(!props.update.updateState);
    }, [facets, props.query, props.update]);

    const responseValues =
        props.response.facets?.find(
            (responseFacet) =>
                responseFacet.name.toLowerCase() ===
                props.facet.funnelbackName.toLowerCase()
        )?.allValues ?? [];
    const responseValuesByData = new Map(
        responseValues.map((value) => [value.data.toLowerCase().trim(), value])
    );

    let secondLevelAutoSelect: string | undefined;
    const checkboxes = facets.map((facet, index) => {
        if (
            index > 0 &&
            !hasValue(props.query.facets[facets[index - 1].meta])
        ) {
            return null;
        }

        const rawValue = props.query.facets[facet.meta];
        const currentValue = Array.isArray(rawValue)
            ? (rawValue[0] ?? '')
            : String(rawValue ?? '');
        const normalizedCurrentValue = currentValue.toLowerCase().trim();
        const values = (facet.values ?? [])
            .filter((value) => {
                const normalizedValue = value.data.toLowerCase().trim();
                return (
                    responseValuesByData.has(normalizedValue) ||
                    normalizedCurrentValue === normalizedValue
                );
            })
            .map((value) => ({
                ...value,
                responseValue: responseValuesByData.get(
                    value.data.toLowerCase().trim()
                ),
            }));

        if (index === 1 && props.response.summary.fullyMatching !== undefined) {
            const fullyMatchingValues = values.filter(
                ({ responseValue }) =>
                    responseValue?.count === props.response.summary.fullyMatching
            );

            if (fullyMatchingValues.length === 1) {
                secondLevelAutoSelect = fullyMatchingValues[0].data
                    .toLowerCase()
                    .trim();
            }
        }

        if (!values.length) return null;

        const inputPrefix = `meta_${facet.meta}_sand--${props.mobile ? 'mobile' : 'desktop'}`;

        return (
            <div
                className="v26-finder__filter v26-finder__drillDown__level"
                key={`${facet.meta}-${index}`}
            >
                <fieldset>
                    <legend className={index === 0 ? "sr-only" : undefined}>
                        {index === 0 ? facet.name : `${facet.name}${values.length > 1 && 's' || ''} in ${props.query.facets[facets[index - 1].meta]}`}
                    </legend>
                    {values.map(({ data, label, responseValue }) => {
                        const normalizedValue = data.toLowerCase().trim();
                        const inputId = `${inputPrefix}--${encodeURIComponent(data)}`;
                        const checked = normalizedCurrentValue === normalizedValue;

                        return (
                            <div
                                className="v26-finder_filters__checkbox_wrap"
                                key={data}
                            >
                                <input
                                    type="checkbox"
                                    id={inputId}
                                    name={`f±${props.facet.funnelbackName}|${facet.meta}`}
                                    className="v26-finder_filters__checkbox"
                                    value={normalizedValue}
                                    checked={checked}
                                    onChange={() => {
                                        if (index === 0 && checked) {
                                            attemptedAutoSelects.current.clear();
                                        }
                                        setFacet(
                                            index,
                                            checked ? '' : normalizedValue
                                        );
                                    }}
                                />
                                <label
                                    className="v26-finder_filters__label v26-finder_filters__label--always"
                                    htmlFor={inputId}
                                >
                                    {label}
                                    {responseValue && responseValue.count > 0
                                        ? <LabelCount count={responseValue.count} />
                                        : ''}
                                </label>
                            </div>
                        );
                    })}
                </fieldset>
            </div>
        );
    });

    useEffect(() => {
        if (secondLevelAutoSelect === undefined || !facets[1]) return;

        const rawValue = props.query.facets[facets[1].meta];
        const currentValue = Array.isArray(rawValue)
            ? (rawValue[0] ?? '')
            : String(rawValue ?? '');
        const parentValue = props.query.facets[facets[0].meta];
        const autoSelectKey = JSON.stringify([
            facets[0].meta,
            parentValue,
            facets[1].meta,
            secondLevelAutoSelect,
        ]);

        if (attemptedAutoSelects.current.has(autoSelectKey)) return;

        attemptedAutoSelects.current.add(autoSelectKey);
        if (currentValue.toLowerCase().trim() !== secondLevelAutoSelect) {
            setFacet(1, secondLevelAutoSelect);
        }
    }, [facets, props.query.facets, secondLevelAutoSelect, setFacet]);

    if (facets.length === 0) return null;

    const content = checkboxes?.some( el => el !== null) ? <div className="v26-finder__drillDown">{checkboxes}</div> : null;

    return props.facet.accordion && !props.matrixState && content ? (
        <Accordion
            title={props.facet.name}
            matrixState={false}
            totalChecked={selectedCount}
        >
            {content}
        </Accordion>
    ) : (
        content
    );
}

Finder__DrillDown.propTypes = {
    facet: PropTypes.object.isRequired,
    query: PropTypes.object.isRequired,
    response: PropTypes.object.isRequired,
    update: PropTypes.object.isRequired,
    mobile: PropTypes.bool,
    matrixState: PropTypes.bool,
};

export default Finder__DrillDown;
