import React from "react";
import PropTypes from "prop-types";
import type { ResultsBayesEvents } from "../../../types/cards/card";
import { decodeHtml } from "../../../util";

function formatShortDate(day: string, month: string) {
  const months = [
      "Jan",
      "Feb",
      "Mar",
      "Apr",
      "May",
      "Jun",
      "Jul",
      "Aug",
      "Sep",
      "Oct",
      "Nov",
      "Dec",
    ],
    monthShort = months[Number.parseInt(month) - 1];

  return (
    <time>
      <span className="events-listing__day">{day}</span>
      <span className="events-listing__month">{monthShort}</span>
    </time>
  );
}

/**
 * Render a Funnelback result as an event card.
 *
 * @param {object} props React props.
 * @return {object} - React component.
 */
function Finder__bayes_event(props: ResultsBayesEvents) {
  const startTime12 = props.details.listMetadata?.startTime12?.[0],
    audienceValue = props.details.listMetadata?.audience?.[0],
    shortDate =
      props.details.listMetadata?.day &&
      props.details.listMetadata?.month &&
      formatShortDate(props.details.listMetadata?.day[0], props.details.listMetadata?.month[0]),
    audience =
      audienceValue && (
        <p
          className="events-listing__audience news-article__anchor"
        >
          {audienceValue}
        </p>
      ),
    eventStartTime = startTime12 ? (
      <div className="events-listing__metadata">{startTime12}</div>
    ) : null;

  return (
    <li className="card--bayes-event">
        <div className="events-time__wrap">
            {shortDate}
        </div>
        <div className="event-listing__details">
            <div className="event-listing__details__column">
                {eventStartTime}
                <div className="events-listing__title"><a href={props.details.liveUrl}>{decodeHtml(props.details.title)}</a></div>
            </div>
            <div className="event-listing__details__column">
                {audience}
            </div>
        </div>
    </li>
  );
}

Finder__bayes_event.propTypes = {
  details: PropTypes.object,
};

export default Finder__bayes_event;
